import{_ as e,c as d,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Add-Product Search (Create-Order)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-products-list","title":"Add-Product Search (Create-Order)","description":"The slim product search behind the admin Create-Order \\"Add Product\\" modal. NOT the product listing — for the full product list with all columns and filters use the List Products datagrid. Returns ALL statuses by default (admin sees disabled / draft products too). Booking products ARE listed but blocked when added to an admin draft cart.","query":"query AdminProducts($first: Int, $after: String, $type: String, $sku: String) {\\n  adminProducts(first: $first, after: $after, type: $type, sku: $sku) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        sku\\n        type\\n        name\\n        status\\n        price\\n        formattedPrice\\n        baseImageUrl\\n        isSaleable\\n      }\\n    }\\n    pageInfo { hasNextPage endCursor }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 30,\\n  \\"type\\": \\"simple\\",\\n  \\"sku\\": \\"SP-001\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminProducts\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/admin_products/2512\\",\\n            \\"_id\\": 2512,\\n            \\"sku\\": \\"SP-001\\",\\n            \\"type\\": \\"simple\\",\\n            \\"name\\": \\"Arctic Cozy Knit Unisex Beanie\\",\\n            \\"status\\": 1,\\n            \\"price\\": 14,\\n            \\"formattedPrice\\": \\"$14.00\\",\\n            \\"baseImageUrl\\": \\"http://localhost:8000/cache/medium/product/2512/Muc0qeWks34MTZaxf38s6DBmfqMqrCxku81Uo8EB.webp\\",\\n            \\"isSaleable\\": true\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": { \\"hasNextPage\\": false, \\"hasPreviousPage\\": false, \\"endCursor\\": \\"MA==\\", \\"startCursor\\": \\"MA==\\" },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/list.md","filePath":"api/graphql-api/admin/catalog/products/list.md"}'),a={name:"api/graphql-api/admin/catalog/products/list.md"};function n(i,t,c,s,l,u){return r(),d("div",null,t[0]||(t[0]=[o('<h1 id="add-product-search-create-order" tabindex="-1">Add-Product Search (Create-Order) <a class="header-anchor" href="#add-product-search-create-order" aria-label="Permalink to &quot;Add-Product Search (Create-Order)&quot;">​</a></h1><p>The slim product <strong>search</strong> that powers the admin <strong>Create Order</strong> screen&#39;s &quot;Add Product&quot; modal — the GraphQL counterpart of <code>GET /api/admin/products</code>. Cursor pagination via <code>first</code> / <code>after</code>.</p><div class="warning custom-block"><p class="custom-block-title">This is not the product listing</p><p>For the full admin product listing — every column plus all the Channel / Name / SKU / Attribute Family / Price / ID / Status / Type filters — use <a href="/api/graphql-api/admin/catalog/products.html">List Products</a> (the <code>adminCatalogProducts</code> query). This page documents only the Create-Order search tool.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminProducts(first: Int, after: String, query: String, sku: String, type: String, status: Int, categoryId: Int, channel: String, locale: String)</code></td><td>Query (cursor)</td></tr></tbody></table><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arg</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>first</code></td><td><code>Int</code></td><td>Page size (default <code>30</code>, max <code>50</code>)</td></tr><tr><td><code>after</code></td><td><code>String</code></td><td>Cursor from a previous <code>pageInfo.endCursor</code></td></tr><tr><td><code>query</code></td><td><code>String</code></td><td>Free-text — matches SKU OR product name (partial)</td></tr><tr><td><code>sku</code></td><td><code>String</code></td><td>Exact SKU</td></tr><tr><td><code>type</code></td><td><code>String</code></td><td><code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>downloadable</code>, <code>grouped</code>, <code>virtual</code>, <code>booking</code></td></tr><tr><td><code>status</code></td><td><code>Int</code></td><td><code>0</code> (disabled) or <code>1</code> (enabled) — omit to get both</td></tr><tr><td><code>categoryId</code></td><td><code>Int</code></td><td>Filter by category ID</td></tr><tr><td><code>channel</code></td><td><code>String</code></td><td>Channel code for value resolution</td></tr><tr><td><code>locale</code></td><td><code>String</code></td><td>Locale code for value resolution</td></tr></tbody></table><h2 id="how-it-differs-from-the-storefront-products-query" tabindex="-1">How it differs from the storefront <code>products</code> query <a class="header-anchor" href="#how-it-differs-from-the-storefront-products-query" aria-label="Permalink to &quot;How it differs from the storefront `products` query&quot;">​</a></h2><ul><li>No automatic <code>status = 1</code> filter — admin sees all statuses.</li><li>Booking products are listed (but cannot be added to an admin draft cart — see the <a href="/api/graphql-api/admin/sales/carts/add-item.html">Add Item to Cart</a> errors list).</li><li>Returns a slim row (9 fields) rather than the full storefront product schema.</li></ul><h2 id="booking-products" tabindex="-1">Booking Products <a class="header-anchor" href="#booking-products" aria-label="Permalink to &quot;Booking Products&quot;">​</a></h2><p>Booking products are returned by this query for admin visibility. Attempting to add one to an admin draft cart via <code>addItemAdminCart</code> returns an error message &quot;Booking products cannot be added to an admin draft order.&quot; — this matches the Bagisto monolith Create-Order UI which has no booking partial.</p>',11)]))}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
